'use strict';
const accountViews={
 dashboard:{eyebrow:'YOUR DEMO ACCOUNT',title:'A safe place to explore your Toyota options.',body:'Choose a synthetic profile, review the illustrative account, or open Smart Service Guardian for the personalized service decision.',cards:[['Smart Service Guardian','Review maintenance, local evidence and a 12-month keep vs. upgrade comparison.','guardian.html'],['Account details','See the synthetic identity, vehicle and contract information used in this demo.','#details'],['Payments','Understand why payments are deliberately unavailable in this no-banking sandbox.','#payments']]},
 details:{eyebrow:'ACCOUNT DETAILS',title:'Synthetic identity and vehicle record.',body:'These are demo-only facts, never a connected Toyota Financial Services account.',cards:[['Demo customer','Alex Morgan · Austin, Texas synthetic profile.',null],['Vehicle snapshot','2018 Toyota Camry SE · odometer, tire pressure, and battery snapshot available in Guardian.',null],['Service and contract context','Paid-off contract fixture with a profile-linked brake estimate and recorded service history.','guardian.html#overview']]},
 payments:{eyebrow:'PAYMENTS',title:'A transparent view of the demo contract.',body:'No bank information is collected and no payment can be made. This page explains the financial inputs used elsewhere.',cards:[['Current contract payment','$0/month because the Alex fixture represents a paid-off vehicle.',null],['Payoff and transaction history','No real payoff, statement, or transaction data is connected to this hackathon sandbox.',null],['Affordability workspace','Separate upfront liquidity from ongoing monthly affordability.','guardian.html#compare']]},
 protection:{eyebrow:'VOLUNTARY PROTECTION',title:'Understand protection before you rely on it.',body:'This sandbox cannot look up real coverage. Guardian clearly labels its synthetic coverage fixture and asks you to verify actual plan terms.',cards:[['Alex demo coverage','$0 applicable coverage in the default profile; other synthetic profiles demonstrate explicit fixtures.',null],['How benefits affect service cost','Review the estimate, benefit, and customer-cost waterfall.','guardian.html#local'],['Official plan questions','Use official Toyota Financial Services resources for real plan questions.','https://www.toyotafinancial.com/us/en/planning_tools/faq.html']]},
 planning:{eyebrow:'PLANNING TOOLS',title:'Plan the next decision, not a transaction.',body:'Use the Guardian to record a self-reported service update, review local evidence, and compare near-term cash-flow scenarios.',cards:[['My maintenance','Review or update planned service items.','guardian.html#maintenance'],['Local service offers','See clearly labeled provider research.','guardian.html#local'],['Keep vs. upgrade','See the 12-month comparison and its assumptions.','guardian.html#compare']]},
 financing:{eyebrow:'EXPLORE FINANCING',title:'Illustrative financing, grounded by public references.',body:'Compare multiple upgrade candidates while keeping synthetic planning terms separate from current public Toyota research.',cards:[['Purchase and lease comparison','Select a Corolla Hybrid, Camry, or Prius and compare purchase or lease cash flow.','guardian.html#compare'],['Current public references','Review cached fuel, MSRP, lease, and regional Toyota finance research.','guardian.html#local'],['Approval status','No credit pull, prequalification, approval, or personalized rate occurs in this demo.',null]]},
 lease:{eyebrow:'END OF LEASE',title:'Lease planning with the right context.',body:'The demo can compare a lease illustration, but it does not represent an active contract or personalized offer.',cards:[['Lease illustration','Choose a vehicle and switch the acquisition path to Lease illustration.','guardian.html#compare'],['Mileage and cash due','Review annual driving, one-time cash due, and monthly affordability as separate inputs.',null],['Official end-of-lease resources','Open Toyota Financial Services in a new tab.','https://www.toyotafinancial.com/us/en/planning_tools/end_of_lease_options.html']]}
};
function renderAccount(){const key=location.hash.slice(1)||'dashboard',v=accountViews[key]||accountViews.dashboard;document.getElementById('account-page').innerHTML=`<section class="hero"><div class="eyebrow red">${v.eyebrow}</div><h1>${v.title}</h1><p>${v.body}</p><span class="badge">Synthetic demo · No real account access</span></section><nav class="tabnav" aria-label="Demo account sections">${['dashboard','details','payments','protection','planning','financing','lease'].map(x=>`<a class="${x===key?'active':''}" href="#${x}">${x==='dashboard'?'Dashboard':x[0].toUpperCase()+x.slice(1)}</a>`).join('')}</nav><section class="summary-grid">${v.cards.map(([title,text,href])=>`<article class="card summary-card"><div class="summary-top"><span>${title}</span>${href?icon('arrow'):''}</div><p>${text}</p>${href?`<a class="btn secondary small" href="${href}" ${href.startsWith('http')?'target="_blank" rel="noopener"':''}>Open ${icon('arrow')}</a>`:'<span class="badge">Demo account context</span>'}</article>`).join('')}</section><div class="integration-note">Each tab now has a distinct purpose: account facts stay here; service, research, affordability, and next-step work opens only when it needs Guardian.</div>`;hydrateIcons();}
window.addEventListener('hashchange',renderAccount);renderAccount();
